:root{--bg:#020b12;--panel:#071c27;--line:rgba(86,210,238,.16);--text:#effcff;--muted:#8eabb7;--cyan:#43d1f0;--green:#64e7bd}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--bg);color:var(--text);font-family:Inter,system-ui,sans-serif;overflow-x:hidden}a{color:inherit;text-decoration:none}.shell{width:min(1180px,calc(100% - 32px));margin:auto}.energy{position:fixed;inset:0;z-index:-1;overflow:hidden;background:radial-gradient(circle at 50% 15%,rgba(30,160,190,.17),transparent 32%),linear-gradient(#020a11,#03131d 55%,#020a11)}.energy:before{content:"";position:absolute;inset:-35%;background:repeating-radial-gradient(circle at 50% 50%,transparent 0 100px,rgba(67,209,240,.035) 101px 102px);animation:spin 32s linear infinite}.header{position:sticky;top:0;z-index:20;background:rgba(2,11,18,.82);backdrop-filter:blur(18px);border-bottom:1px solid var(--line)}.nav{min-height:70px;display:flex;align-items:center;justify-content:space-between}.brand{display:flex;align-items:center;gap:10px;font-weight:850}.brand img{width:40px;height:40px;object-fit:contain;border-radius:10px}.brand b{color:var(--cyan)}.links{display:flex;gap:5px}.links a{padding:10px 12px;border-radius:10px;color:#9db7c0;font-size:11px}.links a:hover,.links a.active{background:rgba(67,209,240,.08);color:#fff}.links i{color:var(--cyan);margin-right:6px}.menu{display:none;width:42px;height:42px;border:1px solid var(--line);border-radius:12px;background:transparent;color:#dff9ff;font-size:18px}.hero{padding:86px 0 65px;text-align:center}.eyebrow{color:var(--cyan);font-size:10px;letter-spacing:.2em;text-transform:uppercase}.hero h1{font-size:clamp(42px,7vw,76px);letter-spacing:-.055em;margin:14px 0}.hero p{max-width:700px;margin:auto;color:var(--muted);line-height:1.8;font-size:14px}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin-top:40px}.metric,.article,.plant{border:1px solid var(--line);background:linear-gradient(145deg,rgba(8,38,52,.88),rgba(3,21,30,.82));border-radius:18px}.metric{padding:22px;text-align:left}.metric i{color:var(--cyan)}.metric small{display:block;margin-top:15px;color:#7295a1;text-transform:uppercase;letter-spacing:.1em;font-size:9px}.metric strong{display:block;font-size:25px;margin-top:6px}.unavailable{color:#7895a0!important;font-size:14px!important}.section{padding:60px 0}.head{margin-bottom:24px}.head .eyebrow{display:block}.head h2{font-size:34px;margin:7px 0}.head p{color:var(--muted);font-size:12px;line-height:1.7}.articles{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.article{padding:21px}.article i{font-size:19px;color:var(--green)}.article h3{margin:12px 0 8px}.article p{color:var(--muted);font-size:12px;line-height:1.7}.plants{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.plant{padding:19px}.plant-top{display:flex;justify-content:space-between;gap:8px}.plant h3{margin:4px 0 15px;font-size:17px}.status{font-size:8px;color:var(--green);background:rgba(100,231,189,.09);padding:5px 8px;border-radius:99px;height:max-content}.plant-row{display:flex;justify-content:space-between;border-top:1px solid rgba(255,255,255,.055);padding:9px 0;color:#8caab4;font-size:10px}.plant-row strong{color:#d9edf2}.empty{padding:28px;border:1px dashed var(--line);border-radius:16px;color:var(--muted);text-align:center}.footer{border-top:1px solid var(--line);padding:32px 0 45px;color:#6e8e99;font-size:10px}@keyframes spin{to{transform:rotate(360deg)}}@media(max-width:800px){.metrics{grid-template-columns:1fr 1fr}.articles,.plants{grid-template-columns:1fr 1fr}}@media(max-width:650px){.shell{width:calc(100% - 24px)}.links{display:none}.menu{display:block}.hero{padding:60px 0 45px}.metrics,.articles,.plants{grid-template-columns:1fr}.hero h1{font-size:45px}.section{padding:45px 0}}@media(prefers-reduced-motion:reduce){*,*:before{animation:none!important;scroll-behavior:auto!important}}
