<main><section class="hero shell"><span class="eyebrow"><i class="fa-solid fa-leaf"></i> Responsible energy</span><h1>Sustainability</h1><p>{{ $brand['tagline'] }} Our sustainability view is built from approved project data and published company content—not invented environmental claims.</p><div class="metrics">@foreach([['capacity_mw','fa-bolt','Installed capacity','MW'],['generation_mwh','fa-chart-line','Annual generation','MWh'],['co2_tonnes','fa-seedling','CO₂ reduction','tonnes'],['efficiency','fa-gauge-high','Average efficiency','%']] as [$key,$icon,$label,$unit])<article class="metric"><i class="fa-solid {{ $icon }}"></i><small>{{ $label }}</small>@if($metrics[$key] !== null)<strong>{{ number_format($metrics[$key],2) }} {{ $unit }}</strong>@else<strong class="unavailable">Data unavailable</strong>@endif</article>@endforeach</div></section>
<section class="section shell"><div class="head"><span class="eyebrow">Published content</span><h2>Our sustainability approach</h2><p>These editorial blocks are controlled from the administration system. Unpublished or future content is never exposed here.</p></div>@if($content->isNotEmpty())<div class="articles">@foreach($content as $item)<article class="article"><i class="fa-solid fa-leaf"></i><h3>{{ $item->title }}</h3><p>{{ $item->excerpt ?: \Illuminate\Support\Str::limit(strip_tags($item->content),180) }}</p></article>@endforeach</div>@else<div class="empty"><i class="fa-regular fa-circle-info"></i><br>No sustainability content has been published yet.</div>@endif</section>
<section class="section shell"><div class="head"><span class="eyebrow">Project impact</span><h2>Plant-level data</h2><p>Only values stored against each power plant are presented. Missing fields remain unavailable rather than being replaced with assumptions.</p></div>@if($plants->isNotEmpty())<div class="plants">@foreach($plants as $plant)<article class="plant"><div class="plant-top"><div><h3>{{ $plant->name }}</h3><span style="color:#7895a0;font-size:10px">{{ $plant->location ?: 'Location unavailable' }}</span></div><span class="status">{{ ucfirst($plant->status ?: 'unknown') }}</span></div>@foreach([['Capacity', $plant->capacity_kw !== null ? number_format($plant->capacity_kw/1000,2).' MW' : null],['Generation', $plant->annual_generation_mwh !== null ? number_format($plant->annual_generation_mwh,2).' MWh' : null],['CO₂ reduction', $plant->co2_reduction_tonnes !== null ? number_format($plant->co2_reduction_tonnes,2).' t' : null],['Efficiency', $plant->efficiency_percent !== null ? number_format($plant->efficiency_percent,2).'%' : null]] as [$label,$value])<div class="plant-row"><span>{{ $label }}</span><strong>{{ $value ?? 'Unavailable' }}</strong></div>@endforeach<a href="{{ route('projects.show',$plant->slug) }}" style="display:block;margin-top:12px;color:var(--cyan);font-size:10px">View project <i class="fa-solid fa-arrow-right"></i></a></article>@endforeach</div>@else<div class="empty">No power plant data is available yet.</div>@endif</section></main><footer class="footer"><div class="shell">© {{ date('Y') }} {{ $brand['name'] }} · Sustainability data is sourced from approved records.</div></footer>
